    descriptionAdvanced: {
      de: "Der Hafen von Su'ao, an der Nordostküste Taiwans im Landkreis Yilan gelegen, ist einer der fünf großen internationalen Häfen der Insel und von strategischer Bedeutung. Er wurde in den 1970er Jahren im Rahmen der \"Zehn Großen Bauprojekte\" umfassend ausgebaut und 1978 für den Verkehr geöffnet, um die Überlastung des Hafens von Keelung zu lindern. Der Hafen ist durch hohe Berge auf drei Seiten geschützt, was ihn zu einem idealen natürlichen Tiefwasserhafen macht, der auch bei schwierigen Wetterbedingungen sicher ist. Neben seiner Rolle als bedeutender Handelshafen für den Export von Holz, Zement und Mineralien dient Su'ao auch als wichtiger Stützpunkt für die taiwanesische Marine. Die Region ist zudem für ihren Fischereihafen Nanfang'ao bekannt, der direkt an den Handelshafen angrenzt und einer der produktivsten Fischereistandorte Taiwans ist. In den letzten Jahren wurden die Hafenanlagen modernisiert, um größere Containerschiffe abfertigen zu können und die regionale Wirtschaft weiter zu stärken. Die malerische Lage zwischen dem Pazifik und den Bergen macht den Hafen zudem zu einem interessanten Ziel für den maritimen Tourismus.",
      hu: "A Tajvan északkeleti partján, Yilan megyében található Su'ao kikötője a sziget öt nagy nemzetközi kikötőjének egyike, és kiemelkedő stratégiai jelentőséggel bír. Az 1970-es években, a \"Tíz Nagy Építési Projekt\" keretében fejlesztették ki, és 1978-ban nyitották meg a forgalom előtt, hogy tehermentesítsék a túlzsúfolt Keelung kikötőjét. A kikötőt három oldalról magas hegyek védik, ami ideális természetes mélyvízi kikötővé teszi, amely még kedvezőtlen időjárási körülmények között is biztonságos menedéket nyújt. Amellett, hogy fontos kereskedelmi kapu a faáru, a cement és az ásványi anyagok exportja számára, Su'ao a tajvani haditengerészet egyik legfontosabb bázisaként is szolgál. A régió híres a Nanfang'ao halászkikötőről is, amely közvetlenül a kereskedelmi kikötő mellett található, és Tajvan egyik legtermékenyebb halászati központja. Az elmúlt években a kikötői létesítményeket korszerűsítették, hogy nagyobb konténerszállító hajókat is fogadhassanak, ezzel is erősítve a regionális gazdaságot. A Csendes-óceán és a hegyek közötti festői elhelyezkedése miatt a kikötő a tengeri turizmus számára is egyre vonzóbb célponttá válik.",
      ro: "Portul Su'ao, situat pe coasta de nord-est a Taiwanului, în județul Yilan, este unul dintre cele cinci mari porturi internaționale ale insulei și deține o importanță strategică majoră. Acesta a fost dezvoltat extensiv în anii 1970, ca parte a „Celor Zece Mari Proiecte de Construcție”, și a fost deschis traficului în 1978 pentru a decongestiona portul Keelung. Portul este protejat pe trei laturi de munți înalți, ceea ce îl face un port natural de adâncime ideal, oferind siguranță chiar și în condiții meteorologice dificile. Pe lângă rolul său de poartă comercială importantă pentru exportul de cherestea, ciment și minerale, Su'ao servește și ca o bază navală esențială pentru marina taiwaneză. Regiunea este, de asemenea, cunoscută pentru portul de pescuit Nanfang'ao, adiacent portului comercial, care este unul dintre cele mai productive centre de pescuit din Taiwan. În ultimii ani, facilitățile portuare au fost modernizate pentru a găzdui nave portcontainere mai mari și pentru a sprijini economia regională. Locația pitorească între Oceanul Pacific și munți face din port o destinație interesantă și pentru turismul maritim.",
      en: "The Port of Su'ao, located on Taiwan's northeastern coast in Yilan County, is one of the island's five major international ports and holds significant strategic importance. It was extensively developed during the 1970s as part of the \"Ten Major Construction Projects\" and opened for traffic in 1978 to relieve congestion at the Port of Keelung. The harbor is shielded by high mountains on three sides, creating an ideal natural deep-water port that remains safe even during adverse weather conditions. In addition to its role as a vital commercial gateway for exporting timber, cement, and minerals, Su'ao also serves as a critical naval base for the Taiwanese Navy. The region is further renowned for the Nanfang'ao fishing port, located directly adjacent to the commercial harbor, which stands as one of Taiwan's most productive fishing hubs. Recent modernizations have upgraded the port's facilities to handle larger container vessels, further bolstering the regional economy. Its picturesque setting between the Pacific Ocean and the mountains also makes the port an increasingly popular destination for maritime tourism.",
      es: "El puerto de Su'ao, en el condado de Yilan, es un puerto pequeño en la costa noreste de Taiwán. Inaugurado en 1973, sirve principalmente como puerto pesquero y para el transporte de carga. Tiene una profundidad de 6 a 10 metros y una capacidad anual de unos 200.000 TEU. También es una base importante para la Guardia Costera de Taiwán. Cerca se encuentran los acantilados de tiza de Su'ao.",
      pt: "O porto de Su'ao, no condado de Yilan, é um porto pequeno na costa nordeste de Taiwan. Inaugurado em 1973, serve principalmente como porto pesqueiro e para transporte de carga. Possui uma profundidade de 6 a 10 metros e uma capacidade anual de cerca de 200.000 TEU. É também uma base importante para a Guarda Costeira de Taiwan. Perto ficam os penhascos de giz de Su'ao.",
      fr: "Le port de Su'ao, dans le comté d'Yilan, est un petit port sur la côte nord-est de Taïwan. Ouvert en 1973, il sert principalement de port de pêche et pour le transport de marchandises. Sa profondeur varie de 6 à 10 mètres et sa capacité annuelle est d'environ 200 000 EVP. C'est également une base importante pour les garde-côtes taïwanais. Les falaises de craie de Su'ao se trouvent à proximité.",
    },
